create table if not exists users(id bigserial primary key,name text not null,phone text unique not null,password_hash text not null,plan text not null default 'free',plan_expires timestamptz,created_at timestamptz not null default now());
create table if not exists shops(id bigserial primary key,owner_id bigint unique not null references users(id) on delete cascade,name text not null,slug text unique not null,city text default 'Yaoundé',phone text,description text default '',created_at timestamptz not null default now());
create table if not exists products(id bigserial primary key,shop_id bigint not null references shops(id) on delete cascade,name text not null,description text default '',price numeric(12,2) not null,stock integer not null default 0,image_url text default '',category text default 'Général',active boolean not null default true,created_at timestamptz not null default now());
create table if not exists orders(id bigserial primary key,shop_id bigint not null references shops(id) on delete cascade,customer_name text not null,customer_phone text not null,address text default '',total numeric(12,2) not null,status text not null default 'new',created_at timestamptz not null default now());
create table if not exists order_items(id bigserial primary key,order_id bigint not null references orders(id) on delete cascade,product_id bigint not null references products(id),quantity integer not null,unit_price numeric(12,2) not null);
create table if not exists payment_requests(id bigserial primary key,user_id bigint not null references users(id) on delete cascade,plan text not null,amount numeric(12,2) not null,transaction_ref text not null,proof text default '',status text not null default 'pending',created_at timestamptz not null default now(),approved_at timestamptz);